CREATE TABLE [dbo].[ccTipoCalif](	  [calif_id] SMALLINT NOT NULL	, [Description] VARCHAR(60) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [orden] TINYINT NOT NULL DEFAULT(255)	, [CanReprogram] BIT NOT NULL DEFAULT((0))	, [Calif_Status] BIT NOT NULL DEFAULT((1))	, [EndConversation] BIT NULL DEFAULT((0))	, [GraphColor] VARCHAR(15) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT('1DB4E2')	, CONSTRAINT [PK_ccTipoCalif] PRIMARY KEY ([calif_id] ASC))